import time, requests
H = {'User-Agent':'Mozilla/5.0 (Windows NT 10.0; Win64; x64)','Referer':'https://stats.nba.com/','Origin':'https://www.nba.com','Accept':'application/json, text/plain, */*','x-nba-stats-origin':'stats','x-nba-stats-token':'true','Accept-Language':'en-US,en;q=0.9'}
try:
    r = requests.get('https://cdn.nba.com/static/json/staticData/scheduleLeagueV2.json', headers=H, timeout=20)
    print('CONTROL cdn.nba.com: HTTP', r.status_code, len(r.content), 'bytes', flush=True)
except Exception as e:
    print('CONTROL cdn.nba.com FAILED:', type(e).__name__, str(e)[:140], flush=True)
tests = [('scoreboardv2','https://stats.nba.com/stats/scoreboardv2?GameDate=01%2F15%2F2026&LeagueID=00&DayOffset=0'),('leaguegamefinder','https://stats.nba.com/stats/leaguegamefinder?LeagueID=00&Season=2025-26&SeasonType=Regular+Season&PlayerOrTeam=T')]
for name, url in tests:
    print('===', name, '===', flush=True)
    ok = False
    for i in range(3):
        t = time.time()
        try:
            r = requests.get(url, headers=H, timeout=45)
            dt = time.time() - t
            print('  attempt', i+1, 'HTTP', r.status_code, 'in', round(dt,1), 's', len(r.content), 'bytes', flush=True)
            if r.status_code == 200:
                ok = True
                break
        except Exception as e:
            dt = time.time() - t
            print('  attempt', i+1, type(e).__name__, 'after', round(dt,1), 's:', str(e)[:140], flush=True)
        time.sleep(5 * (i + 1))
    print('  RESULT', name, 'SUCCESS' if ok else 'FAILED', flush=True)
print('DIAGNOSTIC DONE', flush=True)
